/* Yu-Gi-Oh! internals shared by src/ygo (the rules themselves are EDOPro's: ygo_edo.c). */
#ifndef MOEMON_YGO_INTERNAL_H
#define MOEMON_YGO_INTERNAL_H
#include "ygo/duel.h"

#define NO_OBJ 0xFF

/* Fusion Monsters' materials, from their text (ygo_fusions.c, generated by tools/ygo/gen_catalog.py): what the special
 * duelists' decks are built around */
#define YGO_MAT_ANY 0x8000      /* | race: any monster of that race (YGO_RACE_*) */
#define YGO_MAT_ATTR 0x4000     /* | attribute */
struct YgoFusion
{
    uint16_t card;
    uint16_t materials[5];
};
const struct YgoFusion *Ygo_FusionOf(unsigned card);
/* The opponents' decks of the Game Boy Advance Yu-Gi-Oh! games and goatformat.com's guides (ygo_npc_decks.c, generated by
 * tools/ygo/rate_npc_decks.sh), weakest first: rating is their Elo from AI-against-AI duels */
struct YgoNpcDeck
{
    const char *name, *game, *gameName;
    uint16_t rating;
    uint8_t count;
    const uint16_t *cards;
    uint8_t strength;   /* goatformat.com's decks ("GOAT"): how strong their guide says they are, 1-4 (0: the GBA's) */
};
extern const struct YgoNpcDeck gYgoNpcDecks[];
extern const unsigned gYgoNpcDeckCount;
/* one of them as cards that can be played (src/ygo/ygo_rating.c): 0 when it can't make a deck */
int Ygo_NpcDeckCards(unsigned index, uint16_t main[60], uint16_t extra[15]);
/* The generic duelists' decks from YGOPRODeck (src/ygo/ygo_npc_pool.c, graphics/ygo/npc_pool.bin; docs/YGO_DECISIONS.md
 * "NPC decks from YGOPRODeck"), weakest first, each with its duel rating; gen: the YU-GI-OH! GEN (MP_YgoGen) */
unsigned Ygo_PoolCount(void);
int Ygo_PoolPick(int target, unsigned gen, uint32_t seed);          /* near target (< 0: any) the GEN allows; -1 none */
/* ... no more competitive than comp (0 casual, 1 strong, 2 meta, 3 tournament), rated lo-hi (< 0: no bound) */
int Ygo_PoolPickIn(int target, unsigned gen, unsigned comp, int lo, int hi, uint32_t seed);
unsigned Ygo_PoolComp(unsigned index);
void Ygo_FieldDebugStanding(unsigned standing, unsigned tier);   /* tests: mp ygo standing S TIER */
int Ygo_PoolQuantile(unsigned gen, unsigned share);                 /* the rating share/1024 of the way up */
int Ygo_PoolRange(unsigned gen, int *lo, int *hi);
int Ygo_PoolCards(unsigned index, uint16_t main[60], uint16_t extra[15]);   /* 0 when it can't make 40 */
int Ygo_PoolInfo(unsigned index, char *name, size_t size, unsigned *rating, unsigned *year, unsigned *placing);
void Ygo_PoolNoteMet(int index);

/* Power ratings (src/ygo/ygo_card_ratings.c, made by tools/ygo/rate_cards.sh; never shown as numbers) and what they
 * say (src/ygo/ygo_rating.c): a deck's rating from its main deck's cards, the chance one side beats another, what
 * each AI level gives away (the player counted as playing like the SKILLED level until their record says more) */
extern const int16_t gYgoCardRating[YGO_CARD_COUNT + 1];
extern const int16_t gYgoLevelRating[4];
extern const int32_t gYgoDeckFitA, gYgoDeckFitB;
int Ygo_DeckRating(const uint16_t *main);
unsigned Ygo_Chance(int mine, int theirs);
#define Ygo_LevelRating(level) gYgoLevelRating[(level) > 3 ? 3 : (level)]
#define Ygo_PlayerRating() gYgoLevelRating[2]
/* After a duel against the computer (mine, theirs: ratings with level / skill counted): the skill moves */
struct YgoCollection;
void Ygo_SkillResult(struct YgoCollection *c, int mine, int theirs, int won);
#endif
